          <div v-if="loading" class="chart-loading">Loading clinic activity…</div><div v-else-if="!chartRows.length" class="chart-loading">No visit data is available yet.</div><div v-else class="chart" role="group" aria-label="Patient visits chart"><div class="chart-y"><span v-for="n in [1, .75, .5, .25, 0]" :key="n">{{ localNumber(Math.round(peakValue * n)) }}</span></div><div class="chart-body"><div class="chart-lines"><i v-for="n in 5" :key="n" /></div><svg viewBox="0 0 700 170" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#20b4aa" stop-opacity=".22" /><stop offset="100%" stop-color="#20b4aa" stop-opacity="0" /></linearGradient></defs><path :d="chartAreaPath" fill="url(#area)"/><path :d="chartPath" fill="none" stroke="#16a99e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path v-if="chartRows.length > 1" :d="chartRows.map((row, i) => `${i ? 'L' : 'M'}${chartRows.length === 1 ? 350 : i * 700 / (chartRows.length - 1)} ${150 - row.prescriptions / peakValue * 125}`).join(' ')" fill="none" stroke="#99c9cd" stroke-width="2" stroke-dasharray="6 5"/></svg><div class="chart-hover"><button v-for="(day, i) in days" :key="chartRows[i]?.date" :aria-label="`${day}: ${localNumber(chartValues[i] || 0)} visits`" @mouseenter="chartIndex = i" @focus="chartIndex = i" @click="chartIndex = i"><span v-if="chartIndex === i" class="chart-tooltip">{{ localNumber(chartValues[i] || 0) }} visits<small>{{ formatDateTime(`${chartRows[i]?.date}T08:00:00Z`) }}</small></span></button></div><div class="chart-x"><span v-for="(day, i) in days" :key="day + i" :title="day"><span class="chart-day-full">{{ day.slice(0, 3) }}</span><span class="chart-day-short">{{ day.slice(0, 1) }}</span></span></div></div></div>
        </WidgetPanel>
        <WidgetPanel v-else-if="widget.id === 'distribution'" class="distribution-widget" title="Visit distribution" subtitle="Current chart period"><template #action><UIcon name="i-lucide-chart-pie" class="muted-icon" /></template><div class="donut" :style="{ '--distribution': `${distribution[1]?.percent || 0}%` }"><div><strong>{{ localNumber(totalVisits) }}</strong><span>All visits</span></div></div><div class="distribution-list"><div v-for="entry in distribution" :key="entry.label"><span><i class="legend-dot" :class="entry.tone" />{{ entry.label }}</span><b>{{ localNumber(entry.percent) }}% <small>{{ localNumber(entry.count) }}</small></b></div></div></WidgetPanel>
        <WidgetPanel v-else-if="widget.id === 'patients'" class="patients-widget" title="Recent patients" subtitle="Patients from your latest recorded visits"><template #action><UButton to="/patients" variant="link" trailing-icon="i-lucide-arrow-right">All patients</UButton></template><div class="table-search"><UInput v-model="search" icon="i-lucide-search" placeholder="Search patient name or ID..." aria-label="Search patients" class="w-full" /></div><div class="table-scroll"><table><thead><tr><th>Patient</th><th>Code</th><th>Last visit</th><th>Prescription</th><th><span class="sr-only">Details</span></th></tr></thead><tbody><tr v-for="treatment in recentPatients" :key="treatment.patient.id"><td><div class="patient-cell"><span class="patient-avatar" :class="patientTone(treatment.patient.id)">{{ initials(treatment.patient.name) }}</span><span><strong>{{ treatment.patient.name }}</strong><small>{{ localNumber(treatment.patient.age) }} years · {{ treatment.patient.gender }}</small></span></div></td><td>{{ treatment.patient.code }}</td><td class="time-cell">{{ formatDateTime(treatment.recordedAtUtc) }}</td><td>{{ localNumber(treatment.medicationCount) }} items</td><td><UButton icon="i-lucide-chevron-right" variant="ghost" color="neutral" :aria-label="`${treatment.patient.name} Details`" @click="detail = treatment" /></td></tr><tr v-if="!loading && !recentPatients.length"><td colspan="5" class="empty-table">{{ search ? 'No matching patients found.' : 'No patient visits have been recorded yet.' }}</td></tr></tbody></table></div><div class="table-footer"><span>{{ localNumber(recentPatients.length) }} recent patients</span><span><span class="live-dot" />{{ refreshing ? 'Updating…' : 'Live data' }}</span></div></WidgetPanel>
        <WidgetPanel v-else-if="widget.id === 'activity'" class="activity-widget" title="Recent activity" subtitle="Latest saved treatments"><template #action><span class="today-tag">{{ localNumber(summary?.treatmentsToday || 0) }} today</span></template><div v-if="loading" class="chart-loading">Loading recent activity…</div><div v-else-if="!recentActivity.length" class="chart-loading">No activity has been recorded yet.</div><div v-else class="timeline"><div v-for="(event, i) in recentActivity" :key="event.id" class="timeline-item"><span class="timeline-icon" :class="['teal', 'blue', 'purple', 'orange'][i % 4]"><UIcon :name="event.icon" /></span><div><h3>{{ event.title }}</h3><p>{{ event.text }}</p><small>{{ event.time }}</small></div></div></div><div class="care-note"><UIcon name="i-lucide-heart-handshake" /><div><strong>Better care starts with better organization.</strong><p>RoghtiaSystem, your everyday partner.</p></div></div></WidgetPanel>
      </template>
    </div>
    <footer class="page-footer"><span>RoghtiaSystem <span>·</span> Built for better care</span><span><UIcon name="i-lucide-shield-check" /> Your care is our priority</span></footer>
    <UModal v-model:open="customize" title="Customize dashboard" description="Show, hide or reorder widgets."><template #body><div v-for="(w, i) in widgets" :key="w.id" class="widget-option"><USwitch v-model="w.visible" :label="w.label" /><div><UButton icon="i-lucide-arrow-up" variant="ghost" :disabled="i === 0" aria-label="Move up" @click="move(i, -1)" /><UButton icon="i-lucide-arrow-down" variant="ghost" :disabled="i === widgets.length - 1" aria-label="Move down" @click="move(i, 1)" /></div></div><p class="saved-note">Changes are saved automatically on this device.</p></template></UModal>
    <UModal :open="!!detail" title="Patient visit summary" description="Details from the selected patient's latest visit." @update:open="detail = null"><template #body><div v-if="detail" class="patient-detail"><span class="patient-avatar" :class="patientTone(detail.patient.id)">{{ initials(detail.patient.name) }}</span><h2>{{ detail.patient.name }}</h2><p>{{ detail.patient.code }} · {{ localNumber(detail.patient.age) }} years · {{ detail.patient.gender }}</p><p>{{ localNumber(detail.medicationCount) }} prescribed medication items · {{ localNumber(detail.clinicalNoteCount) }} clinical notes</p><p>Blood pressure: <bdi dir="ltr">{{ detail.bloodPressure || '—' }}</bdi></p><p>{{ formatDateTime(detail.recordedAtUtc) }}</p></div></template></UModal>
  </div>
</template>
